package app

import (
	"errors"
	"strconv"
	"strings"
)

// ParseDuration parses durations like "2d", "4h", "2d4h" or "90m" into minutes.
// Units: d (days), h (hours), m (minutes). Each unit may appear once, in that order.
func ParseDuration(s string) (int, error) {
	if s == "" {
		return 0, errors.New("empty duration")
	}
	total, num := 0, ""
	seen := map[rune]bool{}
	for _, r := range s {
		switch {
		case r >= '0' && r <= '9':
			num += string(r)
		case strings.ContainsRune("dhm", r):
			if num == "" || seen[r] {
				return 0, errors.New("invalid duration: " + s)
			}
			seen[r] = true
			n, _ := strconv.Atoi(num)
			total += n * map[rune]int{'d': 1440, 'h': 60, 'm': 1}[r]
			num = ""
		default:
			return 0, errors.New("invalid unit in: " + s)
		}
	}
	if num != "" {
		return 0, errors.New("missing unit in: " + s)
	}
	return total, nil
}

